import urllib.request, urllib.parse, re
query='rs8176749 rs8176743 rs8176720 ABO A B allele'
req=urllib.request.Request('https://duckduckgo.com/html/?q='+urllib.parse.quote(query), headers={'User-Agent':'Mozilla/5.0'})
try:
    text=urllib.request.urlopen(req, timeout=20).read().decode('utf-8','ignore')
    for m in re.finditer(r'result__a["'^>]*>(.*?)</a>'"', text, re.S):
        print(re.sub('<.*?>','',m.group(1))[:200])
except Exception as e: print('ERR',e)
PY"

/bin/bash -lc "python - <<'PY'
import urllib.request, json
for rs in ['8176749','8176743','8176720','8176715','2519093','8176704','8176693','8176668']:
    url=f'https://api.ncbi.nlm.nih.gov/variation/v0/refsnp/{rs}'
    try:
        data=json.load(urllib.request.urlopen(url, timeout=20))
        print('rs'+rs)
        for p in data.get('primary_snapshot_data',{}).get('placements_with_allele',[])[:3]:
            if p.get('is_ptlp'):
                print(p.get('seq_id'), p.get('placement_annot',{}).get('seq_id_traits_by_assembly',[])[:1])
                for a in p.get('alleles',[])[:5]:
                    spdi=a.get('allele',{}).get('spdi',{})
                    print(spdi)
    except Exception as e: print('ERR',rs,e)
PY"

